import{_ as t,a,o as i,a6 as n}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Sitemaps","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/marketing/search-seo/sitemaps/index.md","filePath":"api/graphql-api/admin/marketing/search-seo/sitemaps/index.md","lastUpdated":1789385991000}'),s={name:"api/graphql-api/admin/marketing/search-seo/sitemaps/index.md"};function r(o,e,d,h,c,p){return i(),a("div",null,e[0]||(e[0]=[n('<h1 id="sitemaps" tabindex="-1">Sitemaps <a class="header-anchor" href="#sitemaps" aria-label="Permalink to &quot;Sitemaps&quot;">​</a></h1><p>A <strong>sitemap</strong> is an XML file that lists your store&#39;s public URLs so search engines can crawl them efficiently. Each definition records where the index file lives, which channels it covers and, once built, which XML files it produced for each of them. It mirrors the admin <strong>Marketing → Search &amp; SEO → Sitemaps</strong> screen.</p><h2 id="how-a-sitemap-works" tabindex="-1">How a sitemap works <a class="header-anchor" href="#how-a-sitemap-works" aria-label="Permalink to &quot;How a sitemap works&quot;">​</a></h2><p>A sitemap has three parts: a <strong>definition</strong> (where its files go), the <strong>channels</strong> it covers, and a <strong>generation</strong> step that builds the actual XML.</p><ul><li><strong>Definition</strong> — <code>fileName</code> is the index file&#39;s name (must end with <code>.xml</code>) and <code>path</code> is the directory it lives in (must start and end with <code>/</code>). Together they set where the sitemap index is written.</li><li><strong>Channels</strong> — <code>channels</code> is the list of channel ids the sitemap covers, and at least one is required. Generation runs once per channel, so a sitemap covering none produces nothing.</li><li><strong>Generation</strong> — the <a href="/api/graphql-api/admin/marketing/search-seo/sitemaps-generate.html">generate</a> action walks each channel&#39;s root category subtree together with the products and pages assigned to that channel, writes an index file plus per-batch XML files under <code>sitemaps/{channel}/</code>, and records what it wrote.</li></ul><p><strong>One channel, one set of files.</strong> Each channel gets its own index and child files, and the URLs inside them use that channel&#39;s hostname — so a storefront served on a second domain is crawled under that domain. <code>urls</code> returns the public index URL per channel, which is the link to submit to a search engine.</p><p><strong>Generated paths.</strong> After a generate run, the detail query exposes <code>generatedFiles</code> — one entry per channel with its <code>hostname</code>, <code>index</code> and <code>sitemaps[]</code>. It is empty before the first generation. <code>generatedAt</code> records when the files were last built.</p><p><strong>Generation is explicit.</strong> Creating or updating a sitemap definition does <strong>not</strong> auto-build the XML — you must call the generate action yourself. Generation runs synchronously, so the response carries the written paths once finished. A sitemap covering no channel is refused, since there is nothing to walk. If sitemap generation is disabled in store configuration, the generate action still succeeds but produces no files.</p><p><strong>Relation to SEO.</strong> A sitemap feeds search engines the URLs that the rest of the <strong>Search &amp; SEO</strong> menu — <a href="/api/graphql-api/admin/marketing/search-seo/url-rewrites/">URL Rewrites</a>, <a href="/api/graphql-api/admin/marketing/search-seo/search-terms/">Search Terms</a>, and <a href="/api/graphql-api/admin/marketing/search-seo/search-synonyms/">Search Synonyms</a> — works to keep discoverable.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/sitemaps-list.html">List</a></td><td><code>adminMarketingSitemaps</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/sitemaps-detail.html">Detail</a></td><td><code>adminMarketingSitemap</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/sitemaps-create.html">Create</a></td><td><code>createAdminMarketingSitemap</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/sitemaps-update.html">Update</a></td><td><code>updateAdminMarketingSitemap</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/sitemaps-delete.html">Delete</a></td><td><code>deleteAdminMarketingSitemap</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/search-seo/sitemaps-generate.html">Generate</a></td><td><code>createAdminMarketingSitemapGenerate</code> mutation</td></tr></tbody></table><p><code>generatedFiles</code> resolves only on the <strong>detail</strong> query — list rows carry the definition fields, the channels and their <code>urls</code>.</p>',12)]))}const g=t(s,[["render",r]]);export{m as __pageData,g as default};
